-- Create stocks table if it doesn't exist
-- Note: Java Spring Boot with Hibernate 'ddl-auto: update' creates this automatically.
-- This script is for manual verification and database initialization.

CREATE TABLE IF NOT EXISTS stocks (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) NOT NULL UNIQUE,
    name VARCHAR(100),
    category VARCHAR(50),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index for faster symbol lookups (used by Watchlist and Analysis)
CREATE INDEX IF NOT EXISTS idx_stocks_symbol ON stocks(symbol);

-- Populate stocks table with all BIST symbols
-- If symbols exist, it will skip them to avoid duplicates.
ON CONFLICT (symbol) DO NOTHING;
